import os,base64,json,subprocess
from pathlib import Path
function=base64.b64decode('').decode();changed=[]
for root in [Path('/opt/constellation/auxiliary-publication/source'),Path('/opt/constellation/capture-workers/source'),Path('/opt/constellation/legacy/optima-market-collection-historical.service')]:
 p=root/'market_collection.py'
 if not p.exists():continue
 old=p.read_text();a=old.index('def normalize(');b=old.index('\ndef record(',a);new=old[:a]+function+old[b:];compile(new,str(p),'exec')
 if new==old:continue
 backup=p.with_suffix('.pre1123.py')
 if not backup.exists():backup.write_text(old)
 tmp=p.with_suffix('.1123.tmp');tmp.write_text(new);st=p.stat();os.chmod(tmp,st.st_mode & 0o777);os.chown(tmp,st.st_uid,st.st_gid);tmp.replace(p);changed.append(str(p))
